/**
 * HistoryChart — Multi-panel history playback.
 * 3 panels: trajectory top-down projection + altitude vs time + velocity vs time.
 * Panels linked by time cursor.
 */

import store from '../state.js';
import bus from '../event-bus.js';

class HistoryChart {
    constructor() {
        this.chart = null;
        this.container = null;
        this._resizeHandler = null;
        this._timeUnsub = null;
        this._playbackUnsub = null;
        this._trajectoryUnsub = null;
    }

    mount(container) {
        this.container = container;

        const chartEl = document.createElement('div');
        chartEl.style.width = '100%';
        chartEl.style.height = '100%';
        container.appendChild(chartEl);

        this.chart = echarts.init(chartEl, null, {
            backgroundColor: 'transparent',
        });

        this._buildChart();

        this._resizeHandler = () => this.chart && this.chart.resize();
        window.addEventListener('resize', this._resizeHandler);

        // Listen for time cursor updates
        this._timeUnsub = bus.on('playback-seek', (t) => this._updateTimeCursor(t));
        this._playbackUnsub = bus.on('playback-state-changed', () => {});
        this._trajectoryUnsub = store.subscribe('trajectory', () => this._buildChart());
    }

    unmount() {
        if (this._resizeHandler) { window.removeEventListener('resize', this._resizeHandler); this._resizeHandler = null; }
        if (this._timeUnsub) { bus.off('playback-seek', this._timeUnsub); this._timeUnsub = null; }
        if (this._playbackUnsub) { bus.off('playback-state-changed', this._playbackUnsub); this._playbackUnsub = null; }
        if (this._trajectoryUnsub) { this._trajectoryUnsub(); this._trajectoryUnsub = null; }
        if (this.chart) { this.chart.dispose(); this.chart = null; }
        if (this.container) { this.container.innerHTML = ''; this.container = null; }
    }

    _buildChart() {
        if (!this.chart || this.chart.isDisposed()) return;

        const trajectory = store.get('trajectory');
        const flown = trajectory?.flown || [];

        const times = flown.map(p => p.t != null ? p.t : 0);
        const altitudes = flown.map(p => (p.z != null ? p.z : p.y));
        const trajXY = flown.map(p => [p.x, p.y]);

        // Compute velocity from position deltas
        const velocities = [];
        for (let i = 1; i < flown.length; i++) {
            const dx = flown[i].x - flown[i - 1].x;
            const dy = flown[i].y - flown[i - 1].y;
            const dz = (flown[i].z || flown[i].y) - (flown[i - 1].z || flown[i - 1].y);
            const dt = (flown[i].t || i) - (flown[i - 1].t || (i - 1));
            const speed = dt > 0 ? Math.sqrt(dx * dx + dy * dy + dz * dz) / dt : 0;
            velocities.push([times[i] || i, speed]);
        }

        this.chart.setOption({
            darkMode: true,
            backgroundColor: 'transparent',
            tooltip: {
                trigger: 'axis',
                axisPointer: {
                    type: 'cross',
                    link: [{ xAxisIndex: 'all' }],
                    label: { backgroundColor: '#333' },
                },
            },
            grid: [
                { top: 30, left: 60, right: 20, bottom: '60%', height: '35%' },
                { top: '45%', left: 60, right: 20, bottom: '30%', height: '20%' },
                { top: '72%', left: 60, right: 20, bottom: 10, height: '20%' },
            ],
            xAxis: [
                { gridIndex: 0, type: 'value', name: 'X (m)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 } },
                { gridIndex: 1, type: 'value', name: 'Time (s)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 }, show: true },
                { gridIndex: 2, type: 'value', name: 'Time (s)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 }, show: true },
            ],
            yAxis: [
                { gridIndex: 0, type: 'value', name: 'Y (m)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 }, splitLine: { lineStyle: { color: '#1A1A1A' } } },
                { gridIndex: 1, type: 'value', name: 'Alt (m)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 }, splitLine: { lineStyle: { color: '#1A1A1A' } } },
                { gridIndex: 2, type: 'value', name: 'Speed (m/s)', nameTextStyle: { color: '#616161' }, axisLine: { lineStyle: { color: '#2A2A2A' } }, axisLabel: { color: '#616161', fontSize: 9 }, splitLine: { lineStyle: { color: '#1A1A1A' } } },
            ],
            series: [
                // Panel 1: Top-down trajectory
                {
                    name: '轨迹',
                    type: 'line',
                    xAxisIndex: 0,
                    yAxisIndex: 0,
                    data: trajXY,
                    lineStyle: { color: '#4CAF50', width: 2 },
                    showSymbol: false,
                },
                // Panel 2: Altitude vs time
                {
                    name: '高度',
                    type: 'line',
                    xAxisIndex: 1,
                    yAxisIndex: 1,
                    data: times.map((t, i) => [t, altitudes[i]]),
                    lineStyle: { color: '#00BCD4', width: 1.5 },
                    showSymbol: false,
                },
                // Panel 3: Velocity vs time
                {
                    name: '速度',
                    type: 'line',
                    xAxisIndex: 2,
                    yAxisIndex: 2,
                    data: velocities,
                    lineStyle: { color: '#FFC107', width: 1.5 },
                    showSymbol: false,
                },
            ],
            animation: false,
        });
    }

    _updateTimeCursor(t) {
        if (!this.chart || this.chart.isDisposed()) return;

        this.chart.dispatchAction({
            type: 'showTip',
            seriesIndex: 0,
            dataIndex: this._findIndex(t),
        });
    }

    _findIndex(t) {
        const trajectory = store.get('trajectory');
        const flown = trajectory?.flown || [];
        for (let i = 0; i < flown.length; i++) {
            if ((flown[i].t || i) >= t) return i;
        }
        return flown.length - 1;
    }
}

export { HistoryChart };

text:
/**
 * AlphaPage — Main flight control view.
 * Left panel: environment info + task progress (no chat)
 * Right panel: ViewModeSelector + ViewPanels (3D/video/charts)
 * FloatingBall integration
 * WS handlers: pose, status, alpha_output, alert
 */

import store from '../state.js';
import bus from '../event-bus.js';
import { renderTwoColumn, wsManager } from '../shared.js';
import { ViewModeSelector } from '../components/ViewModeSelector.js';
import { ViewPanel } from '../components/ViewPanel.js';
import { FloatingBall } from '../components/FloatingBall.js';

class AlphaPage {
    constructor() {
        this.container = null;
        this.title = '飞控';
        this.viewPanels = [];
        this.viewModeSelector = null;
        this.floatingBall = null;
        this._boundOnViewModeChanged = this._onViewModeChanged.bind(this);
        this._boundOnViewSourceChanged = this._onViewSourceChanged.bind(this);
        this._boundOnAlert = this._onAlert.bind(this);
    }

    mount(container) {
        this.container = container;
        this.render();
        this._setupSubscriptions();
    }

    unmount() {
        this.viewPanels.forEach(vp => vp.unmount && vp.unmount());
        this.viewPanels = [];
        if (this.floatingBall && this.floatingBall._collapsed) this.floatingBall._collapse();
        bus.off('view-mode-changed', this._boundOnViewModeChanged);
        bus.off('view-source-changed', this._boundOnViewSourceChanged);
        bus.off('alert', this._boundOnAlert);
        this.container = null;
    }

    render() {
        const env = store.get('environment');
        const flight = store.get('flight');

        // Left panel: environment + task progress
        const leftHtml = `
            <div class="alpha-page">
                <div class="card">
                    <div class="card__inner">
                        <div class="card__header"><span class="card__header-accent">[ ENV ]</span> 环境信息</div>
                        <div class="card__body">
                            <div class="alpha-page__env-info">
                                <div class="alpha-page__env-item">
                                    <span class="alpha-page__env-label">TEMP</span>
                                    <span class="alpha-page__env-value">${env.temperature ?? '--'} °C</span>
                                </div>
                                <div class="alpha-page__env-item">
                                    <span class="alpha-page__env-label">HUM</span>
                                    <span class="alpha-page__env-value">${env.humidity ?? '--'} %</span>
                                </div>
                            <div class="alpha-page__env-item">
                                <span class="alpha-page__env-label">WIND</span>
                                <span class="alpha-page__env-value">${env.windSpeed ?? '--'} m/s</span>
                            </div>
                            <div class="alpha-page__env-item">
                                <span class="alpha-page__env-label">DIR</span>
                                <span class="alpha-page__env-value">${env.windDirection ?? '--'}°</span>
                            </div>
                            <div class="alpha-page__env-item">
                                <span class="alpha-page__env-label">PRES</span>
                                <span class="alpha-page__env-value">${env.pressure ?? '--'} hPa</span>
                            </div>
                            <div class="alpha-page__env-item">
                                <span class="alpha-page__env-label">LOC</span>
                                <span class="alpha-page__env-value">${env.location || '--'}</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div class="card">
                    <div class="card__inner">
                        <div class="card__header"><span class="card__header-accent">[ TASK ]</span> 任务进度</div>
                        <div class="card__body">
                            <div class="alpha-page__task-progress">
                                <div class="alpha-page__task-title">
                                    ${flight.taskTitle || 'NO TASK'}
                                </div>
                                <div class="progress-bar" style="margin-bottom: var(--space-3);">
                                    <div class="progress-bar__fill" style="width: ${flight.progress || 0}%"></div>
                                </div>
                                <div style="font-size: var(--text-sm); color: var(--color-text-secondary); margin-bottom: var(--space-3);">
                                    ${flight.currentActionCode ? `[${flight.currentActionCode}] ${flight.currentAction}/${flight.totalActions || 0}` : (flight.currentAction > 0 ? `ACTION ${flight.currentAction}/${flight.totalActions || 0}` : 'STANDBY')}
                                    ${flight.currentActionParams ? `<br><span style="font-family:var(--font-mono);font-size:var(--text-xs);color:var(--color-text-disabled);">PARAMS: ${JSON.stringify(flight.currentActionParams)}</span>` : ''}
                                </div>
                                <div style="font-size: var(--text-sm); color: var(--color-text-secondary);">
                                    MODE: ${flight.mode || '--'}
                                    &nbsp;|&nbsp;STATUS: ${flight.status || 'idle'}
                                </div>
                                <div class="alpha-page__action-list" style="margin-top: var(--space-2);">
                                    ${(store.get('trajectory.actionSequence') || []).slice(0, 10).map((a, i) => `
                                        <div class="alpha-page__action-item ${i === (flight.currentAction || 0) ? 'alpha-page__action-item--active' : ''}">
                                            ${i === (flight.currentAction || 0) ? '>>>' : ' · '} ${a.code || 'ACT_'}${a.params && a.params.target ? ` → (${a.params.target.x?.toFixed(1) || '?'}, ${a.params.target.y?.toFixed(1) || '?'}, ${a.params.target.z?.toFixed(1) || '?'})` : ''}
                                        </div>
                                    `).join('') || ''}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;

        // Use renderTwoColumn helper
        renderTwoColumn(this.container, leftHtml, '', '/// ALPHA FLIGHT CONTROL');

        // Right toolbar: view mode selector
        const toolbarEl = document.getElementById('right-toolbar');
        if (toolbarEl) {
            this.viewModeSelector = new ViewModeSelector(toolbarEl);
            this.viewModeSelector.render();
        }

        // Right view area
        const viewArea = document.getElementById('right-view-area');
        if (viewArea) {
            this._setupViews(viewArea);
        }

        // FloatingBall
        const fbContainer = document.getElementById('floating-ball-container');
        if (fbContainer) {
            this.floatingBall = new FloatingBall(fbContainer);
            this.floatingBall.mount();
        }
    }

    _setupViews(viewArea) {
        // Clear is handled by renderTwoColumn

        const ui = store.get('ui');
        const mode = ui.viewMode || 1;
        const sources = ui.viewSources || ['chart'];

        viewArea.className = 'right-column__view-area';
        if (mode === 1) viewArea.classList.add('right-column__view-area--single');
        else if (mode === 2) viewArea.classList.add('right-column__view-area--double');
        else if (mode === 3) viewArea.classList.add('right-column__view-area--triple');

        this.viewPanels.forEach(vp => vp.unmount && vp.unmount());
        this.viewPanels = [];

        for (let i = 0; i < mode; i++) {
            const source = sources[i] || 'chart';
            const panelEl = document.createElement('div');
            panelEl.style.flex = '1';
            panelEl.style.minWidth = '0';
            panelEl.style.minHeight = '0';
            panelEl.style.border = '1px solid var(--color-border)';
            panelEl.style.position = 'relative';
            viewArea.appendChild(panelEl);

            const vp = new ViewPanel(i, source);
            vp.mount(panelEl);
            this.viewPanels.push(vp);
        }
    }

    _setupSubscriptions() {
        bus.on('view-mode-changed', this._boundOnViewModeChanged);
        bus.on('view-source-changed', this._boundOnViewSourceChanged);
        bus.on('alert', this._boundOnAlert);
    }

    _onViewModeChanged({ mode, sources }) {
        const viewArea = document.getElementById('right-view-area');
        if (!viewArea) return;

        // Re-initialize views
        this._refreshViews(viewArea);
    }

    _onViewSourceChanged({ slot, source, chartType }) {
        if (this.viewPanels[slot]) {
            this.viewPanels[slot].setSource(source, chartType);
        }
    }

    _refreshViews(viewArea) {
        viewArea.innerHTML = '';
        const ui = store.get('ui');
        const mode = ui.viewMode || 1;
        const sources = ui.viewSources || ['chart'];

        viewArea.className = 'right-column__view-area';
        if (mode === 1) viewArea.classList.add('right-column__view-area--single');
        else if (mode === 2) viewArea.classList.add('right-column__view-area--double');
        else if (mode === 3) viewArea.classList.add('right-column__view-area--triple');

        this.viewPanels.forEach(vp => vp.unmount && vp.unmount());
        this.viewPanels = [];

        for (let i = 0; i < mode; i++) {
            const source = sources[i] || 'chart';
            const panelEl = document.createElement('div');
            panelEl.style.cssText = 'flex: 1; min-width: 0; min-height: 0; border: 1px solid var(--color-border); position: relative;';
            viewArea.appendChild(panelEl);

            const vp = new ViewPanel(i, source);
            vp.mount(panelEl);
            this.viewPanels.push(vp);
        }
    }

    _onAlert(payload) {
        if (!payload) return;
        // Alerts are shown as toasts (handled in app.js via bus)
        // This is a hook for page-specific alert handling if needed
    }
}

export { AlphaPage };

