      get innerHTML() {
        return this._text
          .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
      },
    };
  },
};
const { esc, escAttr } = await import('./js/escape.js');

// esc
const t1 = esc('<img src=x onerror=alert(1)>');
