// escAttr with quote breakout
const t2 = escAttr('a" onmouseover="alert(1)');
console.log('escAttr quote:', t2, t2.includes('&quot;') && !t2.includes('" onmouseover') ? 'PASS' : 'FAIL');
const t3 = escAttr("it's");
console.log('escAttr single-quote:', t3, t3.includes('&#39;') ? 'PASS' : 'FAIL');

// ---- ws.js _dispatch payload compat ----
globalThis.window = { __app: {} };
const { WsManager } = await import('./js/ws.js');
const wm = new WsManager('ws://localhost:9999/ws');
// stub websocket + timers
wm.ws = { readyState: 1, send() {}, close() {} };
let captured = [];
wm.on('pose', (payload, full) => captured.push(['pose', payload, full]));
wm.on('*', (payload, full) => captured.push(['star', payload, full]));
