  pose && pose[1].pos && pose[1].pos[0] === 1 && pose[2].type === 'pose' ? 'PASS' : 'FAIL',
  '| star:', star && star[1].pos ? 'PASS' : 'FAIL',
  '| connection payload:', conn.length === 2 ? 'PASS' : 'FAIL');
EOF

